import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.B2QVIpOM.js";const g=JSON.parse('{"title":"中华基金中学 · 2019／20 年度（汇编标注） · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"cfss","school_zh":"中华基金中学","school_en":"The Chinese Foundation Secondary School","grade":"s1","year":"2019-20","year_label":"2019／20 年度（汇编标注）","type":"interview","title":"中华基金中学 · 2019／20 年度（汇编标注） · 中一 · 面试","anonymous":true,"source_ids":["CF012"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/cfss/s1/2019-20-interview.md","filePath":"reports/cfss/s1/2019-20-interview.md"}'),a={name:"reports/cfss/s1/2019-20-interview.md"};function n(p,o,l,i,c,_){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="中华基金中学-·-2019-20-年度-汇编标注-·-中一-·-面试" tabindex="-1">中华基金中学 · 2019／20 年度（汇编标注） · 中一 · 面试 <a class="header-anchor" href="#中华基金中学-·-2019-20-年度-汇编标注-·-中一-·-面试" aria-label="Permalink to &quot;中华基金中学 · 2019／20 年度（汇编标注） · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/cfss">← 返回中华基金中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-cf012" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-cf012" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-cf012}&quot;">​</a></h2><p><strong>资料类型：</strong> 历史面试反馈汇编</p><p><strong>入学途径：</strong> 普通升中</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-模式推定" tabindex="-1">第一轮 · 模式推定 <a class="header-anchor" href="#第一轮-·-模式推定" aria-label="Permalink to &quot;第一轮 · 模式推定&quot;">​</a></h3><blockquote><p><strong>小组面试：</strong> 中文</p><p><strong>四人合作任務</strong></p><p>4人一組，使用雪花片合作砌出高15cm的汽車，限時8分鐘。</p><p><strong>活動感想</strong></p><p>每位考生以2分鐘分享活動體會，並獲發一張紙記下感想。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>文章閱讀</strong></p><p>閱讀文章，找出詞語填充句子（例子為「油然而生」「興趣」），並說明文章主旨。</p><p><strong>語文題型與例子</strong></p><p>題型包括成語、疊詞、反義詞、重組句子及找錯別字。具體例子為：</p><ul><li>大刀____（闊斧）。</li><li>真知____（灼見）。</li><li>平平____（淡淡）。</li><li>「古舊」的反義詞為「新穎」。</li><li>改錯：「他為人熱枕，應該做的事都會做。」將「枕」改為「忱」。</li></ul><p><strong>學校活動問答</strong></p><p>詢問是否參加過學校開放日或講座；如有，哪一部分令考生印象深刻。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>閱讀與語法</strong></p><p>閱讀文章後回答2條相關問題，另有語法題。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 中文</p><p><strong>選校原因</strong></p><p>說明為何選擇本校。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>英文朗讀</strong></p><p>朗讀一篇關於Death Restaurant的文章一次，再回答4條相關問題。</p><p><strong>工業發展圖片題</strong></p><p>iPad顯示4張關於Industrial 1.0、2.0、3.0及4.0的圖片，以圖像為主；只有圖1附有四個工業階段的文字介紹。考生須以英語回答4道問題，例如：</p><ul><li>圖4的紡紗廠屬於哪個工業階段？為甚麼？</li><li>認為Industrial 4.0好嗎？為甚麼？</li></ul></blockquote>',14)])])}const u=t(a,[["render",n]]);export{g as __pageData,u as default};
